//! ocy-ui: Ocy's four Slint UI surfaces, compiled at build time.
//!
//! Every visible string is an input property (the host passes localised text) and every action is a
//! callback. Set `Theme.dark` through [`set_dark`] (or the generated `Theme` global) before showing.
#![deny(clippy::unwrap_used, clippy::expect_used)]

/// Code generated by `slint-build` from `ui/ocy.slint` (lints are relaxed for generated code only).
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used,
    missing_debug_implementations
)]
mod generated {
    slint::include_modules!();
}

pub use generated::*;

/// Switches every surface of `component` between the light and dark palettes.
pub fn set_dark<C: slint::ComponentHandle>(component: &C, dark: bool)
where
    for<'a> Theme<'a>: slint::Global<'a, C>,
{
    component.global::<Theme>().set_dark(dark);
}
